PROGRAM Main
VAR
    Setpoint : REAL := 100.0;
    ProcessValue : REAL := 50.0;
    Kp : REAL := 1.0;
    Ki : REAL := 0.1;
    Kd : REAL := 0.01;
    Error : REAL;
    PrevError : REAL := 0.0;
    Integral : REAL := 0.0;
    ControlOutput : REAL;
    EStop : BOOL := FALSE;
    Pressure : REAL := 50.0;
    HighPressureLimit : REAL := 80.0;
    HighPressureAlarm : BOOL;
    PowerOK : BOOL := TRUE;
    ManualMode : BOOL := TRUE;
    ManualCommand : BOOL := FALSE;
    ActuatorOutput : BOOL := FALSE;
    i : INT;
END_VAR
    Error := Setpoint - ProcessValue;
    Integral := Integral + Ki * Error;
    ControlOutput := Kp * Error + Kd * (Error - PrevError) + Integral;
    ControlOutput := LIMIT(0.0, ControlOutput, 100.0);
    PrevError := Error;
    FOR i := 1 TO 10 DO
        (* Loop for demonstration *);
    END_FOR;
    HighPressureAlarm := Pressure > HighPressureLimit;
    IF EStop THEN
        ActuatorOutput := FALSE;
    END_IF;
    IF NOT PowerOK THEN
        ActuatorOutput := FALSE;
    END_IF;
    IF ManualMode THEN
        ActuatorOutput := ManualCommand;
    END_IF;
    IF HighPressureAlarm THEN
        (* Safety override for high pressure *);
        ActuatorOutput := FALSE;
    END_IF;
END_PROGRAM
